from __future__ import annotations

import json
import unittest

from ledgerlock.format import (
    GENESIS,
    canonical_bytes,
    line_hash,
    normalize_key,
)


class TestNormalizeKey(unittest.TestCase):
    def test_passthrough_ascii(self) -> None:
        self.assertEqual(normalize_key("hello"), "hello")

    def test_nfkd_to_nfc(self) -> None:
        nfd = "e\u0301"
        nfc = "\u00e9"
        self.assertEqual(normalize_key(nfd), nfc)
        self.assertEqual(normalize_key(nfc), nfc)
        self.assertEqual(normalize_key(nfd), normalize_key(nfc))


class TestCanonicalBytes(unittest.TestCase):
    def test_round_trip_unchanged(self) -> None:
        d = {"op": "put", "key": "k", "value": {"v": 1}, "id": "r1", "ts": 100}
        b1 = canonical_bytes(d)
        expected = json.dumps(d, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode(
            "utf-8"
        )
        self.assertEqual(b1, expected)

    def test_deterministic_across_calls(self) -> None:
        d = {"op": "put", "key": "k", "value": 1, "id": "r", "ts": 1}
        self.assertEqual(canonical_bytes(d), canonical_bytes(d))

    def test_non_ascii_preserved(self) -> None:
        d = {"key": "\u00e9"}
        b = canonical_bytes(d)
        self.assertIn(b"\xc3\xa9", b)
        self.assertNotIn(b"\\u00e9", b)
        self.assertEqual(b, canonical_bytes(d))

    def test_key_order_irrelevant(self) -> None:
        a = {"op": "put", "key": "k", "value": 1}
        b = {"value": 1, "key": "k", "op": "put"}
        self.assertEqual(canonical_bytes(a), canonical_bytes(b))

    def test_round_trip_json(self) -> None:
        d = {"op": "put", "key": "k", "value": [1, 2, 3], "id": "r", "ts": 1}
        b1 = canonical_bytes(d)
        b2 = canonical_bytes(json.loads(json.dumps(d)))
        self.assertEqual(b1, b2)


class TestGenesisConstant(unittest.TestCase):
    def test_value_is_seven_char_string(self) -> None:
        self.assertEqual(GENESIS, "GENESIS")
        self.assertEqual(len(GENESIS), 7)


class TestLineHash(unittest.TestCase):
    def test_is_64_lowercase_hex(self) -> None:
        line = {"op": "put", "key": "k", "value": 1, "id": "r", "ts": 1}
        h = line_hash("GENESIS", line)
        self.assertEqual(len(h), 64)
        self.assertTrue(all(c in "0123456789abcdef" for c in h))

    def test_distinct_prev_hash_yields_distinct_result(self) -> None:
        line = {"op": "put", "key": "k", "value": 1, "id": "r", "ts": 1}
        a = line_hash("GENESIS", line)
        b = line_hash("0" * 64, line)
        self.assertNotEqual(a, b)

    def test_ignores_existing_hash_and_prev_hash(self) -> None:
        line_with = {
            "op": "put",
            "key": "k",
            "value": 1,
            "id": "r",
            "ts": 1,
            "hash": "deadbeef" * 8,
            "prev_hash": "feedface" * 8,
        }
        line_without = {"op": "put", "key": "k", "value": 1, "id": "r", "ts": 1}
        self.assertEqual(
            line_hash("GENESIS", line_with),
            line_hash("GENESIS", line_without),
        )

    def test_deterministic(self) -> None:
        line = {"op": "put", "key": "k", "value": 1, "id": "r", "ts": 1}
        self.assertEqual(line_hash("GENESIS", line), line_hash("GENESIS", line))

    def test_genesis_accepted(self) -> None:
        line = {"op": "put", "key": "k", "value": 1, "id": "r", "ts": 1}
        h = line_hash("GENESIS", line)
        self.assertEqual(len(h), 64)


if __name__ == "__main__":
    unittest.main()

